{
  "ref": "spec:openapi",
  "content": {
    "format": "openapi-3.1",
    "title": "Tideglass Marine Data \u2014 a fleet telemetry & vessel-tracking platform ingesting AIS, fuel, and cargo-manifest streams for shipping operators. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the Tideglass Marine Data \u2014 a fleet telemetry & vessel-tracking platform ingesting AIS, fuel, and cargo-manifest streams for shipping operators. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "Tideglass Marine Data \u2014 a fleet telemetry & vessel-tracking platform ingesting AIS, fuel, and cargo-manifest streams for shipping operators. API",
        "version": "1.0.0",
        "description": "Tideglass Vessel Telemetry API: a sprawling REST surface exposing vessel positions, voyage legs, port-call events, fuel-burn reports, and cargo manifests across several API generations (v1 legacy, v2 stable, v3 beta)."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc"
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v2/vessels": {
          "get": {
            "summary": "List vessels (registry)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/vessel-tracks": {
          "get": {
            "summary": "Historical track points",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vessel-positions": {
          "get": {
            "summary": "Live vessel positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/positions": {
          "get": {
            "summary": "DEPRECATED live positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/voyages": {
          "get": {
            "summary": "Voyage records",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/voyage-legs": {
          "get": {
            "summary": "Individual voyage legs",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/port-calls": {
          "get": {
            "summary": "Port call records",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/port-events": {
          "get": {
            "summary": "Port arrival/departure events",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/fuel-reports": {
          "get": {
            "summary": "Fuel burn reports",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/fuel-consumption": {
          "get": {
            "summary": "Fuel consumption telemetry",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/cargo": {
          "get": {
            "summary": "Cargo summaries",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/cargo-manifests": {
          "get": {
            "summary": "Cargo manifests",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vessel-positions/{imo}": {
          "get": {
            "summary": "Single vessel live position",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
